// Rollup tree-shaking - reachability DCE demo
var graph = { main: ["a", "b"], a: ["c"], b: [], c: [], dead1: ["dead2"], dead2: [] };
var live = {};
(function mark(n) { if (live[n]) return; live[n] = 1; (graph[n] || []).forEach(mark); })("main");
var removed = Object.keys(graph).filter(function(k) { return !live[k]; });
console.log("Tool: Rollup | Removes: unused exports");
console.log("Live: " + Object.keys(live).join(", "));
console.log("Eliminated: " + removed.join(", ") + " -> DCE PASS");

